function validSubarraySplit(nums) {
  // Try every set of cut positions between neighbours and keep the valid split with the fewest pieces.
  const n = nums.length;
  const sharesFactor = (a, b) => {
    for (let d = 2; d <= Math.min(a, b); d++) if (a % d === 0 && b % d === 0) return true;
    return false;
  };
  let best = -1;
  for (let mask = 0; mask < 1 << (n - 1); mask++) {
    let first = 0, pieces = 0, ok = true;
    for (let i = 0; i < n && ok; i++) {
      const cutAfter = i === n - 1 || (mask >> i) & 1;
      if (!cutAfter) continue;
      if (!sharesFactor(nums[first], nums[i])) ok = false;
      pieces++;
      first = i + 1;
    }
    if (ok && (best === -1 || pieces < best)) best = pieces;
  }
  return best;
}

