function generate(rand, size) {
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 10);
    const top = rand() < 0.5 ? 12 : 40;
    // A few ones make some splits impossible; otherwise values are small, so factors are often shared.
    return [Array.from({ length: n }, () => (rand() < 0.08 ? 1 : 1 + Math.floor(rand() * top)))];
  }
  const n = 1000;
  const mode = rand();
  if (mode < 0.3) return [Array.from({ length: n }, () => 1 + Math.floor(rand() * 100000))];
  // Otherwise values come from a pool of primes, so shared factors are rarer and the answer grows.
  const primes = [];
  for (let v = 2; primes.length < 160; v++) if (primes.every(p => v % p !== 0)) primes.push(v);
  const poolSize = mode < 0.6 ? 100 + Math.floor(rand() * 60) : 6 + Math.floor(rand() * 30);
  // Products use only primes below 300, so they stay under 10^5.
  const choices = mode < 0.6 ? primes.length : 62;
  const pool = Array.from({ length: poolSize }, () => primes[Math.floor(rand() * choices)]);
  const nums = Array.from({ length: n }, () => {
    const p = pool[Math.floor(rand() * pool.length)];
    return mode < 0.6 || rand() < 0.5 ? p : p * pool[Math.floor(rand() * pool.length)];
  });
  if (mode > 0.9) nums[rand() < 0.5 ? 0 : n - 1] = 1;
  return [nums];
}
